metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "javascript",
    "theme": "default",
    "headStyle": "title",
    "locale": "ko"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "openSvgFile(text)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "call",
          "target": {
            "kind": "named",
            "name": "findModelElement"
          },
          "args": "text",
          "result": "found"
        },
        {
          "id": "b3",
          "kind": "if",
          "text": "!found.ok",
          "yes": {
            "id": "r1",
            "body": [
              {
                "id": "b2",
                "kind": "exit",
                "text": "return openFailure(found.reason)   // noModel · prototype"
              }
            ]
          },
          "no": {
            "id": "r2",
            "body": [
              {
                "id": "b4",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b6",
          "kind": "if",
          "text": "found.element.text is not JSON",
          "yes": {
            "id": "r3",
            "body": [
              {
                "id": "b5",
                "kind": "exit",
                "text": "return openFailure('damaged')"
              }
            ]
          },
          "no": {
            "id": "r4",
            "body": [
              {
                "id": "b7",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b9",
          "kind": "if",
          "text": "version attribute !== JSON version",
          "yes": {
            "id": "r5",
            "body": [
              {
                "id": "b8",
                "kind": "exit",
                "text": "return openFailure('damaged')"
              }
            ]
          },
          "no": {
            "id": "r6",
            "body": [
              {
                "id": "b10",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b11",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d2"
          },
          "args": "value",
          "result": "result"
        },
        {
          "id": "b12",
          "kind": "process",
          "text": "return result"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "parseModel(value)"
      },
      "body": [
        {
          "id": "b14",
          "kind": "if",
          "text": "value.format !== 'ariadne-nsd'",
          "yes": {
            "id": "r7",
            "body": [
              {
                "id": "b13",
                "kind": "exit",
                "text": "return openFailure('damaged')"
              }
            ]
          },
          "no": {
            "id": "r8",
            "body": [
              {
                "id": "b15",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b17",
          "kind": "if",
          "text": "version is not a whole number ≥ 0",
          "yes": {
            "id": "r9",
            "body": [
              {
                "id": "b16",
                "kind": "exit",
                "text": "return openFailure('damaged')"
              }
            ]
          },
          "no": {
            "id": "r10",
            "body": [
              {
                "id": "b18",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b20",
          "kind": "if",
          "text": "version === 0",
          "yes": {
            "id": "r11",
            "body": [
              {
                "id": "b19",
                "kind": "exit",
                "text": "return openFailure('prototype')"
              }
            ]
          },
          "no": {
            "id": "r12",
            "body": [
              {
                "id": "b21",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b23",
          "kind": "if",
          "text": "version > currentFormatVersion",
          "yes": {
            "id": "r13",
            "body": [
              {
                "id": "b22",
                "kind": "exit",
                "text": "return openFailure('newerVersion')"
              }
            ]
          },
          "no": {
            "id": "r14",
            "body": [
              {
                "id": "b24",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b25",
          "kind": "process",
          "text": "migrated = value"
        },
        {
          "id": "b31",
          "kind": "for",
          "text": "for (from = version; from < currentFormatVersion; from += 1)",
          "body": [
            {
              "id": "b26",
              "kind": "process",
              "text": "migrate = migrations.get(from)"
            },
            {
              "id": "b28",
              "kind": "if",
              "text": "migrate === undefined",
              "yes": {
                "id": "r15",
                "body": [
                  {
                    "id": "b27",
                    "kind": "exit",
                    "text": "return openFailure('damaged')"
                  }
                ]
              },
              "no": {
                "id": "r16",
                "body": [
                  {
                    "id": "b29",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            },
            {
              "id": "b30",
              "kind": "process",
              "text": "migrated = migrate(migrated)"
            }
          ]
        },
        {
          "id": "b32",
          "kind": "call",
          "target": {
            "kind": "named",
            "name": "readDocument"
          },
          "args": "migrated",
          "result": "loaded"
        },
        {
          "id": "b34",
          "kind": "if",
          "text": "loaded === null",
          "yes": {
            "id": "r17",
            "body": [
              {
                "id": "b33",
                "kind": "exit",
                "text": "return openFailure('damaged')   // 필드 · id 형식 · 모르는 키"
              }
            ]
          },
          "no": {
            "id": "r18",
            "body": [
              {
                "id": "b35",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b36",
          "kind": "call",
          "target": {
            "kind": "named",
            "name": "invariantCheck"
          },
          "args": "loaded.doc.content",
          "result": "problem"
        },
        {
          "id": "b38",
          "kind": "if",
          "text": "problem !== null",
          "yes": {
            "id": "r19",
            "body": [
              {
                "id": "b37",
                "kind": "exit",
                "text": "return openFailure('damaged')   // 불변식"
              }
            ]
          },
          "no": {
            "id": "r20",
            "body": [
              {
                "id": "b39",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b40",
          "kind": "process",
          "text": "return { ok: true, value: loaded }"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
